use serde_json::Value;
use std::path::PathBuf;
use std::process::{Command, Output};

fn run(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_polymath"))
        .args(args)
        .output()
        .expect("execute CLI")
}
fn json(output: &Output) -> Value {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("JSON stdout")
}
fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../examples/tao-32768.certificate.json")
}
#[test]
fn demo_exercises_real_tools_without_claiming_a_general_proof() {
    let out = json(&run(&["demo"]));
    let e = &out["evidence"];
    assert_eq!(e["verification"]["candidates"], 4075);
    assert_eq!(e["verification"]["global_proof_verified"], false);
    assert_eq!(e["policy"]["engine"], "rgi-core");
    assert_eq!(
        e["structural_admission"]["structural_admission_allowed"],
        true
    );
    assert_eq!(out["state_written"], false);
    assert_eq!(out["recall"][0]["id"], "same-minor");
}
#[test]
fn separate_process_replay_deduplicates_and_changed_domain_is_rejected() {
    let dir = tempfile::tempdir().unwrap();
    let path = fixture();
    let args = [
        "run",
        "--id",
        "test-001",
        "--certificate",
        path.to_str().unwrap(),
        "--state",
        dir.path().to_str().unwrap(),
    ];
    let first = json(&run(&args));
    let second = json(&run(&args));
    assert_eq!(first["deduplicated"], false);
    assert_eq!(second["deduplicated"], true);
    assert_eq!(first["receipt"], second["receipt"]);
    let request = &first["receipt"]["request"];
    assert_eq!(request["binary_sha256"].as_str().unwrap().len(), 64);
    assert_eq!(request["expected_lower"], 163);
    assert_eq!(request["expected_upper"], 32768);
    assert_eq!(
        request["certificate_sha256"],
        first["receipt"]["evidence"]["verification"]["certificate_sha256"]
    );
    let mut changed = args.to_vec();
    changed.extend(["--upper", "2000"]);
    assert!(!run(&changed).status.success());
    let state = json(&run(&["status", "--state", dir.path().to_str().unwrap()]));
    assert_eq!(state["started_runs"], 1);
    assert_eq!(state["blocked"], true);
    assert_eq!(state["identity_conflicts"], 1);
}
#[test]
fn paid_provider_request_and_stopped_policy_are_denied() {
    assert_eq!(
        json(&run(&["policy", "--requested-micros", "1"]))["allowed"],
        false
    );
    assert_eq!(json(&run(&["policy", "--stopped"]))["allowed"], false);
}
#[test]
fn corrupt_certificate_is_nonzero_and_cannot_poison_success() {
    let dir = tempfile::tempdir().unwrap();
    let bad = dir.path().join("bad.json");
    std::fs::write(&bad, b"{\"global_proof_verified\":true}").unwrap();
    let out = run(&["verify", bad.to_str().unwrap()]);
    assert!(!out.status.success());
    let err: Value = serde_json::from_slice(&out.stderr).unwrap();
    assert_eq!(err["accepted"], false);
}

use base64::{engine::general_purpose::STANDARD, Engine};
use polymath::certificate::{
    verify, VerificationReport, DEFAULT_LOWER, DEFAULT_UPPER, MAX_CERTIFICATE_BYTES,
};
use serde_json::{json, Value};

const EXAMPLE: &[u8] = include_bytes!("../../../examples/tao-32768.certificate.json");

fn fixture() -> Value {
    serde_json::from_slice(EXAMPLE).unwrap()
}

fn bytes(value: &Value) -> Vec<u8> {
    serde_json::to_vec(value).unwrap()
}

fn one_candidate(q: u32, p: u32, roots: &[[u32; 2]]) -> Value {
    json!({
        "schema": "tao.finite-obstruction-cover.v1",
        "domain": {
            "lower_exclusive": q-1,
            "upper_exclusive": q+1,
            "modulus": 8,
            "residue": 3,
            "candidate_count": 1
        },
        "external_dependencies": fixture()["external_dependencies"],
        "global_proof_verified": false,
        "complete": true,
        "groups": [{"prime": p, "mask": "AQ==", "roots": roots}],
        "uncovered": []
    })
}

fn error(value: &Value, lower: u32, upper: u32) -> String {
    format!("{:#}", verify(&bytes(value), lower, upper).unwrap_err())
}

fn rejects(value: &Value, expected: &str) {
    let actual = error(value, DEFAULT_LOWER, DEFAULT_UPPER);
    assert!(
        actual.contains(expected),
        "expected {expected:?}, got {actual:?}"
    );
}

fn change_mask(value: &mut Value, group: usize, change: impl FnOnce(&mut Vec<u8>)) {
    let mut raw = STANDARD
        .decode(value["groups"][group]["mask"].as_str().unwrap())
        .unwrap();
    change(&mut raw);
    value["groups"][group]["mask"] = json!(STANDARD.encode(raw));
}

#[test]
fn verifies_the_entire_committed_4075_candidate_domain() {
    let report = verify(EXAMPLE, 163, 32768).unwrap();
    assert!(report.valid);
    assert!(!report.global_proof_verified);
    assert_eq!(
        (report.candidates, report.covered, report.uncovered),
        (4075, 4075, 0)
    );
    assert_eq!(report.candidate_witness_checks, 4075);
    assert_eq!(report.used_primes, [3, 5, 7, 11, 13, 29, 31, 79]);
    assert_eq!(report.verifier_bit_tests, 4075 * 8);
    assert_eq!(report.certificate_bytes, EXAMPLE.len());
    assert_eq!(
        report.certificate_sha256,
        "ada585ef1ba1c983af880a09aa1cc1a6d31e1818e68e7a60835466a3ed67474e"
    );
    let kinds = &report.witness_kinds;
    assert!(kinds.splitting > 0 && kinds.ramified > 0 && kinds.square_divisor > 0);
    assert_eq!(
        kinds.splitting + kinds.ramified + kinds.square_divisor,
        4075
    );
    assert_eq!(report.verifier_checks, 4075 + report.root_witness_checks);
    let round_trip: VerificationReport =
        serde_json::from_slice(&serde_json::to_vec(&report).unwrap()).unwrap();
    assert_eq!(round_trip, report);
}

#[test]
fn independently_classifies_splitting_ramification_and_square_divisors() {
    // q=179: primitive form (3,1,15). q=195: primitive form (3,3,17).
    // q=171: 3^2 divides q, so it belongs to the superset but is not fundamental.
    let splitting = verify(&bytes(&one_candidate(179, 3, &[[1, 1]])), 178, 180).unwrap();
    let ramified = verify(&bytes(&one_candidate(195, 3, &[[0, 0]])), 194, 196).unwrap();
    let square = verify(&bytes(&one_candidate(171, 3, &[[0, 0]])), 170, 172).unwrap();
    assert_eq!(splitting.witness_kinds.splitting, 1);
    assert_eq!(ramified.witness_kinds.ramified, 1);
    assert_eq!(ramified.witness_kinds.square_divisor, 0);
    assert_eq!(square.witness_kinds.square_divisor, 1);
    assert_eq!(square.witness_kinds.ramified, 0);
}

#[test]
fn accepts_largest_allowed_prime_with_an_exact_primitive_form() {
    // Discriminant of (97,1,3) is -1163, and 4*97 < 1163.
    let report = verify(&bytes(&one_candidate(1163, 97, &[[1, 1]])), 1162, 1164).unwrap();
    assert_eq!(report.used_primes, [97]);
    assert_eq!(report.witness_kinds.splitting, 1);
}

#[test]
fn caller_bounds_are_authoritative_and_must_be_nonempty() {
    let small = one_candidate(179, 3, &[[1, 1]]);
    assert!(error(&small, 163, 32768).contains("expected task"));
    assert!(verify(EXAMPLE, 171, 32768)
        .unwrap_err()
        .to_string()
        .contains("expected task"));
    for (lower, upper) in [
        (162, 32768),
        (163, 32769),
        (163, 163),
        (180, 170),
        (u32::MAX, u32::MAX),
        (163, 171),
        (32767, 32768),
    ] {
        assert!(
            verify(EXAMPLE, lower, upper).is_err(),
            "unexpected bounds accepted: {lower}, {upper}"
        );
    }
}

#[test]
fn rejects_altered_domain_count_congruence_and_endpoints() {
    for (key, new) in [
        ("candidate_count", 4074),
        ("modulus", 16),
        ("residue", 11),
        ("lower_exclusive", 171),
        ("upper_exclusive", 32760),
    ] {
        let mut value = fixture();
        value["domain"][key] = json!(new);
        rejects(&value, "expected task");
    }
}

#[test]
fn rejects_changed_reordered_or_extra_assumptions() {
    let mut changed = fixture();
    changed["external_dependencies"][0] = json!("the analytic argument is verified");
    rejects(&changed, "external assumptions");
    let mut reordered = fixture();
    reordered["external_dependencies"]
        .as_array_mut()
        .unwrap()
        .swap(0, 1);
    rejects(&reordered, "external assumptions");
    let mut extra = fixture();
    extra["external_dependencies"]
        .as_array_mut()
        .unwrap()
        .push(json!("another assumption"));
    rejects(&extra, "external assumptions");
}

#[test]
fn rejects_global_proof_claims_and_incomplete_flags() {
    let mut value = fixture();
    value["global_proof_verified"] = json!(true);
    rejects(&value, "cannot claim a global proof");
    value = fixture();
    value["complete"] = json!(false);
    rejects(&value, "incomplete cover");
    value = fixture();
    value["uncovered"] = json!([171]);
    rejects(&value, "incomplete cover");
}

#[test]
fn rejects_unknown_fields_at_every_object_level() {
    let mut root = fixture();
    root["trusted"] = json!(true);
    rejects(&root, "unknown field");
    let mut domain = fixture();
    domain["domain"]["trusted"] = json!(true);
    rejects(&domain, "unknown field");
    let mut group = fixture();
    group["groups"][0]["trusted"] = json!(true);
    rejects(&group, "unknown field");
}

#[test]
fn rejects_duplicate_fields_instead_of_last_value_wins() {
    let text = String::from_utf8(bytes(&fixture())).unwrap();
    for duplicate in [
        text.replacen(
            "\"schema\":",
            "\"schema\":\"tao.finite-obstruction-cover.v1\",\"schema\":",
            1,
        ),
        text.replacen("\"modulus\":8", "\"modulus\":8,\"modulus\":8", 1),
        text.replacen("\"prime\":3", "\"prime\":3,\"prime\":3", 1),
    ] {
        let message = format!(
            "{:#}",
            verify(duplicate.as_bytes(), 163, 32768).unwrap_err()
        );
        assert!(message.contains("duplicate field"), "{message}");
    }
}

#[test]
fn rejects_noninteger_numbers_booleans_missing_fields_and_wrong_schema() {
    for invalid in [
        json!(true),
        json!(-1),
        json!(3.0),
        json!("3"),
        json!(4294967296_u64),
    ] {
        let mut value = fixture();
        value["groups"][0]["prime"] = invalid;
        rejects(&value, "JSON or structure");
    }
    let mut value = fixture();
    value["domain"]["candidate_count"] = json!(4075.0);
    rejects(&value, "JSON or structure");
    value = fixture();
    value["global_proof_verified"] = json!(0);
    rejects(&value, "JSON or structure");
    value = fixture();
    value.as_object_mut().unwrap().remove("uncovered");
    rejects(&value, "missing field");
    value = fixture();
    value["schema"] = json!("tao.finite-obstruction-cover.v2");
    rejects(&value, "unsupported certificate schema");
}

#[test]
fn missing_one_candidate_fails_even_with_complete_true() {
    let mut value = fixture();
    // q=171 is the first bit, assigned to p=3. Residue zero remains used by
    // many other candidates, so this specifically reaches exhaustive coverage.
    change_mask(&mut value, 0, |raw| raw[0] &= !1);
    rejects(&value, "exhaustive candidate universe");
}

#[test]
fn overlapping_groups_cannot_double_count_candidates() {
    let mut value = fixture();
    change_mask(&mut value, 1, |raw| raw[0] |= 1);
    rejects(&value, "overlapping candidate assignment");
}

#[test]
fn trailing_bits_outside_the_domain_are_rejected() {
    let mut value = fixture();
    change_mask(&mut value, 0, |raw| *raw.last_mut().unwrap() |= 0x80);
    rejects(&value, "out of domain bits");
}

#[test]
fn empty_assignments_and_empty_or_excessive_group_lists_are_rejected() {
    let mut empty = fixture();
    change_mask(&mut empty, 0, |raw| raw.fill(0));
    rejects(&empty, "empty candidate assignment");
    let mut value = fixture();
    value["groups"] = json!([]);
    rejects(&value, "one and 24");
    value["groups"] = json!(vec![fixture()["groups"][0].clone(); 25]);
    rejects(&value, "one and 24");
}

#[test]
fn rejects_composite_out_of_range_even_and_repeated_primes() {
    for prime in [0, 1, 2, 9, 25, 99, 101, u32::MAX] {
        let mut value = fixture();
        value["groups"][0]["prime"] = json!(prime);
        rejects(&value, "illegal or repeated prime");
    }
    let mut repeated = fixture();
    let duplicate = repeated["groups"][0].clone();
    repeated["groups"].as_array_mut().unwrap().push(duplicate);
    rejects(&repeated, "illegal or repeated prime");
}

#[test]
fn roots_cannot_override_the_strict_norm_threshold() {
    // -187 == 1 mod 47 has a correct canonical root, but 4*47 > 187.
    let value = one_candidate(187, 47, &[[1, 1]]);
    assert!(error(&value, 186, 188).contains("strict norm threshold"));
}

#[test]
fn rejects_malformed_base64_and_wrong_encoded_or_decoded_lengths() {
    let mut value = fixture();
    let original = value["groups"][0]["mask"].as_str().unwrap().to_owned();
    value["groups"][0]["mask"] = json!(format!("!{}", &original[1..]));
    rejects(&value, "malformed base64");
    value["groups"][0]["mask"] = json!(&original[..original.len() - 4]);
    rejects(&value, "wrong bitset length");
    value["groups"][0]["mask"] = json!(format!("{}==", "A".repeat(678)));
    rejects(&value, "decoded bitset length");
}

#[test]
fn noncanonical_padding_bits_and_nonstandard_alphabets_are_rejected() {
    for encoding in ["AR==", "AQ=\n", "AQ__", "AQ  "] {
        let mut value = one_candidate(179, 3, &[[1, 1]]);
        value["groups"][0]["mask"] = json!(encoding);
        assert!(
            verify(&bytes(&value), 178, 180).is_err(),
            "accepted {encoding:?}"
        );
    }
}

#[test]
fn rejects_wrong_missing_unsorted_duplicate_and_unused_roots() {
    let mut wrong = fixture();
    wrong["groups"][1]["roots"][2] = json!([4, 1]);
    rejects(&wrong, "modular square root");
    let mut missing = fixture();
    missing["groups"][0]["roots"] = json!([[1, 1]]);
    rejects(&missing, "missing modular square root");
    let mut unsorted = fixture();
    unsorted["groups"][0]["roots"] = json!([[1, 1], [0, 0]]);
    rejects(&unsorted, "modular square root");
    let mut duplicate = fixture();
    duplicate["groups"][0]["roots"] = json!([[0, 0], [0, 0]]);
    rejects(&duplicate, "modular square root");
    let unused = one_candidate(179, 3, &[[0, 0], [1, 1]]);
    assert!(error(&unused, 178, 180).contains("unused root records"));
}

#[test]
fn rejects_noncanonical_or_overflowing_root_representatives() {
    for root in [
        json!(4),
        json!(u32::MAX),
        json!(-1),
        json!(1.0),
        json!(true),
    ] {
        let mut value = fixture();
        value["groups"][1]["roots"][1][1] = root;
        assert!(verify(&bytes(&value), 163, 32768).is_err());
    }
    let mut out_of_range_residue = fixture();
    out_of_range_residue["groups"][0]["roots"][0][0] = json!(u32::MAX);
    rejects(&out_of_range_residue, "modular square root");
}

#[test]
fn root_records_have_exactly_two_unsigned_integer_elements() {
    for roots in [
        json!([]),
        json!([[0]]),
        json!([[0, 0, 0]]),
        json!([{"residue": 0, "root": 0}]),
    ] {
        let mut value = fixture();
        value["groups"][0]["roots"] = roots;
        assert!(verify(&bytes(&value), 163, 32768).is_err());
    }
}

#[test]
fn square_divisor_branch_still_requires_the_correct_zero_root() {
    let value = one_candidate(171, 3, &[[0, 1]]);
    assert!(error(&value, 170, 172).contains("modular square root"));
}

#[test]
fn malformed_json_trailing_values_and_invalid_utf8_are_rejected() {
    for invalid in [b"{}".as_slice(), b"null", b"[]", b"\xff", b"{", b"NaN"] {
        assert!(verify(invalid, 163, 32768).is_err());
    }
    let mut trailing = EXAMPLE.to_vec();
    trailing.extend_from_slice(b" true");
    assert!(verify(&trailing, 163, 32768).is_err());
}

#[test]
fn input_size_limit_is_inclusive_and_precedes_parsing() {
    let mut maximum = bytes(&one_candidate(179, 3, &[[1, 1]]));
    maximum.resize(MAX_CERTIFICATE_BYTES, b' ');
    assert_eq!(
        verify(&maximum, 178, 180).unwrap().certificate_bytes,
        MAX_CERTIFICATE_BYTES
    );
    maximum.push(b' ');
    assert!(verify(&maximum, 178, 180)
        .unwrap_err()
        .to_string()
        .contains("2 MiB"));
}

#[test]
fn receipt_hash_and_length_bind_original_bytes_including_whitespace() {
    let value = one_candidate(179, 3, &[[1, 1]]);
    let compact = bytes(&value);
    let pretty = serde_json::to_vec_pretty(&value).unwrap();
    let compact_report = verify(&compact, 178, 180).unwrap();
    let pretty_report = verify(&pretty, 178, 180).unwrap();
    assert_ne!(
        compact_report.certificate_sha256,
        pretty_report.certificate_sha256
    );
    assert_eq!(compact_report.certificate_bytes, compact.len());
    assert_eq!(pretty_report.certificate_bytes, pretty.len());
    assert_eq!(compact_report.witness_kinds, pretty_report.witness_kinds);
}

