#![forbid(unsafe_code)]
use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use polymath::{certificate, integrations, journal};
use serde::Deserialize;
use serde_json::{json, Value};
use std::collections::BTreeSet;
use std::fs::File;
use std::io::Read;
use std::path::{Path, PathBuf};

const MAX_INPUT_BYTES: u64 = 2 * 1024 * 1024;

#[derive(Parser)]
#[command(
    name = "polymath",
    version,
    about = "Turn mathematical claims into reproducible evidence"
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Check the bundled certificate and exercise native rUv integrations. No state or search.
    Demo,
    /// Verify every finite witness against the caller's expected domain.
    Verify {
        certificate: PathBuf,
        #[arg(long, default_value_t = 163)]
        lower: u32,
        #[arg(long, default_value_t = 32768)]
        upper: u32,
    },
    /// Record one exact verification. A completed identity deduplicates across processes.
    Run {
        #[arg(long)]
        id: String,
        #[arg(long)]
        certificate: PathBuf,
        #[arg(long, default_value = ".polymath")]
        state: PathBuf,
        #[arg(long, default_value_t = 163)]
        lower: u32,
        #[arg(long, default_value_t = 32768)]
        upper: u32,
    },
    /// Inspect local verification history without running mathematics.
    Status {
        #[arg(long, default_value = ".polymath")]
        state: PathBuf,
    },
    /// Persistently prevent new recorded verifications. There is no automatic reset.
    Stop {
        #[arg(long, default_value = ".polymath")]
        state: PathBuf,
    },
    /// Retrieve notes using native RuVector HNSW and local hashed token features.
    Recall {
        notes: PathBuf,
        #[arg(long)]
        query: String,
        #[arg(long, default_value_t = 3)]
        limit: usize,
    },
    /// Compare declared bounds only when conclusions and assumptions match.
    Compare { claims: PathBuf },
    /// Exercise the actual rGi policy kernel with a zero provider budget.
    Policy {
        #[arg(long, default_value_t = 0)]
        requested_micros: u64,
        #[arg(long)]
        stopped: bool,
    },
}

fn read_bounded(path: &Path) -> Result<Vec<u8>> {
    let mut data = Vec::new();
    File::open(path)
        .with_context(|| format!("cannot open {}", path.display()))?
        .take(MAX_INPUT_BYTES + 1)
        .read_to_end(&mut data)?;
    if data.len() as u64 > MAX_INPUT_BYTES {
        bail!("input exceeds 2 MiB");
    }
    Ok(data)
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Claim {
    id: String,
    conclusion: String,
    upper_bound: u64,
    relation: String,
    assumptions: Vec<String>,
    evidence_status: String,
    source: String,
}

fn compare(bytes: &[u8]) -> Result<Value> {
    let claims: Vec<Claim> = serde_json::from_slice(bytes)?;
    if claims.is_empty() || claims.len() > 100 {
        bail!("supply 1..100 claims");
    }
    let mut ids = BTreeSet::new();
    for c in &claims {
        if c.id.trim().is_empty()
            || !ids.insert(&c.id)
            || c.conclusion.trim().is_empty()
            || c.upper_bound == 0
            || !["lt", "le"].contains(&c.relation.as_str())
            || c.source.trim().is_empty()
            || !["reported", "reproduced", "reviewed", "formal"]
                .contains(&c.evidence_status.as_str())
            || c.assumptions.is_empty()
            || c.assumptions.iter().any(|a| a.trim().is_empty())
            || c.assumptions.iter().collect::<BTreeSet<_>>().len() != c.assumptions.len()
        {
            bail!("invalid or duplicate claim metadata");
        }
    }
    let mut comparisons = Vec::new();
    for (i, a) in claims.iter().enumerate() {
        for b in claims.iter().skip(i + 1) {
            let matching = a.conclusion == b.conclusion
                && a.relation == b.relation
                && a.assumptions.iter().collect::<BTreeSet<_>>()
                    == b.assumptions.iter().collect::<BTreeSet<_>>();
            let smaller = if matching && a.upper_bound != b.upper_bound {
                Some(if a.upper_bound < b.upper_bound {
                    &a.id
                } else {
                    &b.id
                })
            } else {
                None
            };
            comparisons.push(json!({"left":a.id,"right":b.id,"matching_declared_assumptions":matching,
                "numerically_smaller_claim":smaller,"evidence_statuses":[a.evidence_status,b.evidence_status],
                "evidence_verified_by_this_comparison":false}));
        }
    }
    Ok(
        json!({"comparisons":comparisons,"state_of_the_art_established":false,
        "note":"Metadata comparison only. Source truth, completeness of assumptions, and proof validity require separate review."}),
    )
}

fn execute(cli: Cli) -> Result<Value> {
    match cli.command {
        Commands::Demo => {
            let bytes = include_bytes!("../../../examples/tao-32768.certificate.json");
            let notes: Vec<integrations::ResearchNote> =
                serde_json::from_slice(include_bytes!("../../../examples/research-notes.json"))?;
            Ok(
                json!({"demo":"deterministic verification, no optimization or provider calls",
                "evidence":polymath::verify_evidence(bytes,163,32768)?,
                "recall":integrations::recall(&notes,"same determinant valuation",3)?,
                "state_written":false}),
            )
        }
        Commands::Verify {
            certificate,
            lower,
            upper,
        } => Ok(serde_json::to_value(certificate::verify(
            &read_bounded(&certificate)?,
            lower,
            upper,
        )?)?),
        Commands::Run {
            id,
            certificate,
            state,
            lower,
            upper,
        } => {
            let bytes = read_bounded(&certificate)?;
            Ok(serde_json::to_value(journal::run(
                &state, &id, &bytes, lower, upper,
            )?)?)
        }

        Commands::Status { state } => journal::status(&state),
        Commands::Stop { state } => journal::stop(&state),
        Commands::Recall {
            notes,
            query,
            limit,
        } => {
            let notes: Vec<integrations::ResearchNote> =
                serde_json::from_slice(&read_bounded(&notes)?)?;
            Ok(
                json!({"backend":"ruvector-core HNSW","features":"deterministic hashed tokens, lexical similarity, not neural embeddings",
                "hits":integrations::recall(&notes,&query,limit)?}),
            )
        }
        Commands::Compare { claims } => compare(&read_bounded(&claims)?),
        Commands::Policy {
            requested_micros,
            stopped,
        } => integrations::policy(stopped, requested_micros),
    }
}

fn main() {
    match execute(Cli::parse()) {
        Ok(value) => println!(
            "{}",
            serde_json::to_string_pretty(&value).expect("serialize JSON")
        ),
        Err(error) => {
            eprintln!("{}", json!({"error":format!("{error:#}"),"accepted":false}));
            std::process::exit(1);
        }
    }
}

