/// Run exact verification, zero spend policy, and structural admission.
pub fn verify_evidence(bytes: &[u8], lower: u32, upper: u32) -> Result<Value> {
    let policy = integrations::policy(false, 0)?;
    if policy["allowed"] != true {
        bail!("rGi denied local certificate verification");
    }
    let report = certificate::verify(bytes, lower, upper)?;
    let admission = integrations::admit_verified(&report.certificate_sha256, report.candidates)?;
    if admission["structural_admission_allowed"] != true {
        bail!("Autogenous denied structural admission");
    }
    Ok(
        json!({"verification":report,"policy":policy,"structural_admission":admission,
        "analytic_bound_verified":false,"formal_proof_verified":false}),
    )
}

//! Durable receipts for local verification. This is not the Tao optimizer journal.
use anyhow::{bail, Context, Result};
use fs2::FileExt;
use rusqlite::{params, Connection, OptionalExtension};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::path::Path;

pub const MAX_RUNS: u64 = 4;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RunResult {
    pub deduplicated: bool,
    pub receipt: Value,
}

pub fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 80
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn open(state: &Path) -> Result<(File, Connection)> {
    let absolute = if state.is_absolute() {
        state.to_path_buf()
    } else {
        std::env::current_dir()?.join(state)
    };
    let missing: Vec<_> = absolute
        .ancestors()
        .take_while(|p| !p.exists())
        .map(Path::to_path_buf)
        .collect();
    fs::create_dir_all(state)?;
    // Persist each newly created directory entry before any action can start.
    for directory in missing.iter().rev() {
        if let Some(parent) = directory.parent() {
            File::open(parent)?.sync_all()?;
        }
        File::open(directory)?.sync_all()?;
    }
    let lock_existed = state.join("LOCK").exists();
    let lock = OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(state.join("LOCK"))?;
    lock.try_lock_exclusive()
        .context("another verification owns this state; no work dispatched")?;
    let db_path = state.join("journal.sqlite");
    let existed = db_path.exists();
    if !existed {
        if lock_existed {
            bail!("partial state has a lock but no journal; inspect explicitly");
        }
        let mut entries = fs::read_dir(state)?;
        while let Some(entry) = entries.next().transpose()? {
            if entry.file_name() != "LOCK" {
                bail!("state contains files but no journal; refuse replacement state");
            }
        }
    }
    let db = Connection::open(&db_path)?;
    db.execute_batch("PRAGMA synchronous=FULL; PRAGMA foreign_keys=ON;")?;
    if !existed {
        db.execute_batch(
            "BEGIN IMMEDIATE;
             CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             CREATE TABLE runs (
                 id TEXT PRIMARY KEY, request_hash TEXT NOT NULL, request BLOB NOT NULL,
                 status TEXT NOT NULL CHECK(status IN ('pending','completed','failed')),
                 receipt TEXT, error TEXT,
                 created INTEGER NOT NULL DEFAULT (unixepoch())
             );
             CREATE TABLE conflicts (id TEXT NOT NULL, stored_hash TEXT NOT NULL, attempted_hash TEXT NOT NULL);
             INSERT INTO meta VALUES ('schema','polymath.verification-journal.v1');
             INSERT INTO meta VALUES ('max_runs','4');
             INSERT INTO meta VALUES ('stopped','false');
             COMMIT;",
        )?;
    }
    File::open(state)?.sync_all()?;
    let schema: String = db.query_row("SELECT value FROM meta WHERE key='schema'", [], |r| {
        r.get(0)
    })?;
    let max: String = db.query_row("SELECT value FROM meta WHERE key='max_runs'", [], |r| {
        r.get(0)
    })?;
    if schema != "polymath.verification-journal.v1" || max != "4" {
        bail!("unsupported journal schema or changed allowance; inspect explicitly");
    }
    Ok((lock, db))
}

fn integrity(db: &Connection, state: &Path) -> Result<()> {
    let mut q = db.prepare("SELECT id, receipt FROM runs WHERE status='completed'")?;
    let rows = q.query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?)))?;
    for row in rows {
        let (id, receipt) = row?;
        if !valid_id(&id) {
            bail!("invalid journal identity");
        }
        let on_disk = fs::read(state.join("receipts").join(format!("{id}.json")))
            .context("completed receipt missing; inspect journal before proceeding")?;
        if on_disk != receipt.as_bytes() {
            bail!("completed receipt changed; inspect journal before proceeding");
        }
    }
    Ok(())
}

/// Execute a deterministic certificate verification with no caller supplied code.
/// The receipt exposes certificate, domain, version, and current executable identity.
pub fn run(
    state: &Path,
    id: &str,
    certificate: &[u8],
    lower: u32,
    upper: u32,
) -> Result<RunResult> {
    let binary_hash = digest(&fs::read(std::env::current_exe()?)?);
    let request = serde_json::to_vec(&json!({
        "schema": "polymath.verify-request.v1",
        "certificate_sha256": digest(certificate),
        "expected_lower": lower,
        "expected_upper": upper,
        "binary_sha256": binary_hash,
        "crate_version": env!("CARGO_PKG_VERSION")
    }))?;
    run_operation(state, id, &request, || {
        crate::verify_evidence(certificate, lower, upper)
    })
}

// Private fault-injection seam. Only the fixed verifier above is public.
fn run_operation<F>(state: &Path, id: &str, request: &[u8], operation: F) -> Result<RunResult>
where
    F: FnOnce() -> Result<Value>,
{
    if request.len() > 65536 {
        bail!("verification request exceeds 64 KiB");
    }
    if !valid_id(id) {
        bail!("run id must contain 1..80 ASCII letters, digits, underscores or hyphens");
    }
    let (_lock, db) = open(state)?;
    integrity(&db, state)?;
    let request_hash = digest(request);
    let existing: Option<(String, String, Option<String>)> = db
        .query_row(
            "SELECT request_hash,status,receipt FROM runs WHERE id=?1",
            [id],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
        )
        .optional()?;
    if let Some((stored_hash, status, receipt)) = existing {
        if stored_hash != request_hash {
            db.execute_batch("BEGIN IMMEDIATE;")?;
            db.execute(
                "INSERT INTO conflicts(id,stored_hash,attempted_hash) VALUES(?1,?2,?3)",
                params![id, stored_hash, request_hash],
            )?;
            db.execute("UPDATE meta SET value='true' WHERE key='stopped'", [])?;
            db.execute_batch("COMMIT;")?;
            bail!("run identity conflict; do not retry under another identity");
        }
        if status == "completed" {
            return Ok(RunResult {
                deduplicated: true,
                receipt: serde_json::from_str(&receipt.context("completed receipt absent")?)?,
            });
        }
        bail!("existing run is {status}; explicit inspection required, no retry");
    }
    let unresolved: u64 = db.query_row(
        "SELECT count(*) FROM runs WHERE status!='completed'",
        [],
        |r| r.get(0),
    )?;
    if unresolved > 0 {
        bail!("pending or failed run blocks new work; retain it for inspection");
    }
    let stopped: String = db.query_row("SELECT value FROM meta WHERE key='stopped'", [], |r| {
        r.get(0)
    })?;
    if stopped != "false" {
        bail!("verification journal is stopped");
    }
    let count: u64 = db.query_row("SELECT count(*) FROM runs", [], |r| r.get(0))?;
    if count >= MAX_RUNS {
        bail!("four started local verifications exhausted; allowance cannot be reset here");
    }
    db.execute(
        "INSERT INTO runs(id,request_hash,request,status) VALUES(?1,?2,?3,'pending')",
        params![id, request_hash, request],
    )?;
    let result = operation();
    match result {
        Err(error) => {
            db.execute(
                "UPDATE runs SET status='failed',error=?2 WHERE id=?1",
                params![id, error.to_string()],
            )?;
            Err(error.context("verification failed and remains recorded"))
        }
        Ok(evidence) => {
            let receipt = json!({
                "schema": "polymath.verification-receipt.v1",
                "run_id": id,
                "request_sha256": request_hash,
                "request": serde_json::from_slice::<Value>(request).unwrap_or_else(|_|json!({"encoding":"hex","bytes":request.iter().map(|b|format!("{b:02x}")).collect::<String>()})),
                "operation": "certificate.verify",
                "evidence": evidence,
                "global_proof_verified": false,
                "signed_promotion": false,
                "numerical_optimizer_executed": false,
                "external_provider_spend_micros": 0
            });
            let encoded = serde_json::to_string_pretty(&receipt)?;
            let receipts = state.join("receipts");
            fs::create_dir_all(&receipts)?;
            File::open(state)?.sync_all()?;
            let path = receipts.join(format!("{id}.json"));
            let mut file = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(path)
                .context("receipt creation failed; run retained as pending")?;
            file.write_all(encoded.as_bytes())?;
            file.sync_all()?;
            File::open(&receipts)?.sync_all()?;
            db.execute(
                "UPDATE runs SET status='completed',receipt=?2 WHERE id=?1",
                params![id, encoded],
            )?;
            Ok(RunResult {
                deduplicated: false,
                receipt,
            })
        }
    }
}

pub fn status(state: &Path) -> Result<Value> {
    if !state.join("journal.sqlite").exists() {
        if state.exists() && fs::read_dir(state)?.next().is_some() {
            bail!("partial state without a journal; inspect explicitly");
        }
        return Ok(
            json!({"initialized":false,"scope":"local certificate verification only","max_started_runs":MAX_RUNS}),
        );
    }
    let (_lock, db) = open(state)?;
    integrity(&db, state)?;
    let stopped: String = db.query_row("SELECT value FROM meta WHERE key='stopped'", [], |r| {
        r.get(0)
    })?;
    let mut query =
        db.prepare("SELECT id,status,request_hash,error FROM runs ORDER BY created,id")?;
    let rows = query.query_map([], |r| {
        Ok(json!({
            "id":r.get::<_,String>(0)?, "status":r.get::<_,String>(1)?,
            "request_sha256":r.get::<_,String>(2)?, "error":r.get::<_,Option<String>>(3)?
        }))
    })?;
    let runs: Vec<Value> = rows.collect::<std::result::Result<_, _>>()?;
    let conflicts: u64 = db.query_row("SELECT count(*) FROM conflicts", [], |r| r.get(0))?;
    let unresolved = runs.iter().any(|r| r["status"] != "completed");
    Ok(
        json!({"initialized":true,"scope":"local certificate verification only","stopped":stopped!="false",
        "started_runs":runs.len(),"identity_conflicts":conflicts,"max_started_runs":MAX_RUNS,"blocked":unresolved || stopped!="false" || runs.len()>=MAX_RUNS as usize,"runs":runs}),
    )
}

pub fn stop(state: &Path) -> Result<Value> {
    let (_lock, db) = open(state)?;
    db.execute("UPDATE meta SET value='true' WHERE key='stopped'", [])?;
    drop(db);
    drop(_lock);
    status(state)
}

