        let dir = tempfile::tempdir().unwrap();
        assert!(run_operation(dir.path(), "bad", b"bad", || bail!("invalid witness")).is_err());
        assert!(run_operation(dir.path(), "retry", b"bad", || panic!()).is_err());
        assert_eq!(status(dir.path()).unwrap()["started_runs"], 1);
        let pending = tempfile::tempdir().unwrap();
