    fn caps_and_stop_are_persistent() {
        let dir = tempfile::tempdir().unwrap();
        for i in 0..4 {
            run_operation(dir.path(), &format!("r{i}"), b"x", || Ok(json!(true))).unwrap();
        }
        assert!(run_operation(dir.path(), "r4", b"x", || panic!()).is_err());
        assert!(
            run_operation(dir.path(), "r0", b"x", || panic!())
                .unwrap()
                .deduplicated
        );
