        stop(stopped.path()).unwrap();
        assert!(run_operation(stopped.path(), "new", b"x", || panic!()).is_err());
    }
    #[test]
    fn tampered_receipts_and_concurrent_writer_are_rejected() {
        let dir = tempfile::tempdir().unwrap();
        run_operation(dir.path(), "one", b"x", || Ok(json!(true))).unwrap();
        fs::write(dir.path().join("receipts/one.json"), "tampered").unwrap();
        assert!(run_operation(dir.path(), "two", b"x", || panic!()).is_err());
        let locked = tempfile::tempdir().unwrap();
        let (_lock, _db) = open(locked.path()).unwrap();
        assert!(run_operation(locked.path(), "new", b"x", || panic!()).is_err());
    }
    #[test]
    fn path_traversal_and_empty_ids_are_rejected() {
        let dir = tempfile::tempdir().unwrap();
        for id in ["../escape", "", "two/parts"] {
            assert!(run_operation(dir.path(), id, b"x", || panic!()).is_err());
        }
        assert!(!dir.path().join("journal.sqlite").exists());
    }
    #[test]
    fn conflict_is_retained_and_blocks_new_identities() {
        let dir = tempfile::tempdir().unwrap();
        run_operation(dir.path(), "one", b"original", || Ok(json!(true))).unwrap();
        assert!(run_operation(dir.path(), "one", b"changed", || panic!()).is_err());
        assert!(run_operation(dir.path(), "two", b"changed", || panic!()).is_err());
        let state = status(dir.path()).unwrap();
        assert_eq!(state["identity_conflicts"], 1);
        assert_eq!(state["stopped"], true);
        assert_eq!(state["started_runs"], 1);
    }
    #[test]
    fn missing_journal_never_replaces_partial_state() {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join("LOCK"), "").unwrap();
        assert!(run_operation(dir.path(), "one", b"x", || panic!()).is_err());
        assert!(!dir.path().join("journal.sqlite").exists());
        assert!(status(dir.path()).is_err());
    }
}

//! Exact verification of a finite obstruction cover, conditional on its stated
//! external assumptions. This module does not establish an analytic cutoff,
//! the congruence reduction, or a general mathematical proof.
//!
//! The expected interval supplied to [`verify`] is authoritative. Every integer
//! congruent to 3 modulo 8 in that interval receives an independently checked
//! witness; neither a producer's count nor a hash substitutes for those checks.

use anyhow::{ensure, Context, Result};
use base64::{engine::general_purpose::STANDARD, Engine};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

/// Maximum serialized input size, including whitespace.
pub const MAX_CERTIFICATE_BYTES: usize = 2 * 1024 * 1024;
/// Smallest supported exclusive lower bound.
pub const DEFAULT_LOWER: u32 = 163;
/// Largest supported exclusive upper bound.
pub const DEFAULT_UPPER: u32 = 32768;

const SCHEMA: &str = "tao.finite-obstruction-cover.v1";
const DEPENDENCIES: [&str; 3] = [
    "the analytic argument implies q < upper_exclusive",
    "a hypothetical class number one fundamental discriminant q > 163 is 3 modulo 8",
    "a noninert prime p with 4*p < q obstructs class number one",
];

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Certificate {
    schema: String,
    domain: Domain,
    external_dependencies: Vec<String>,
    global_proof_verified: bool,
    complete: bool,
    groups: Vec<Group>,
    uncovered: Vec<u32>,
}

#[derive(Debug, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct Domain {
    lower_exclusive: u32,
    upper_exclusive: u32,
    modulus: u32,
    residue: u32,
    candidate_count: usize,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Group {
    prime: u32,
    mask: String,
    roots: Vec<[u32; 2]>,
}

/// Exact counts of the accepted candidate witnesses.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct WitnessKinds {
    pub splitting: usize,
    pub ramified: usize,
    pub square_divisor: usize,
}

/// Receipt for a successful exhaustive finite verification.
///
/// `certificate_sha256` and `certificate_bytes` describe the original input
/// bytes, including whitespace. They are not a canonical JSON size metric and
/// are produced only after all mathematical and coverage checks succeed.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct VerificationReport {
    pub valid: bool,
    pub lower_exclusive: u32,
    pub upper_exclusive: u32,
    pub candidates: usize,
    pub covered: usize,
    pub uncovered: usize,
    pub certificate_sha256: String,
    pub certificate_bytes: usize,
    pub used_primes: Vec<u32>,
    pub candidate_witness_checks: usize,
    pub root_witness_checks: usize,
    pub verifier_bit_tests: usize,
    pub verifier_checks: usize,
    pub witness_bits: usize,
    pub witness_kinds: WitnessKinds,
    pub global_proof_verified: bool,
}

fn bounds(lower: u32, upper: u32) -> Result<(u32, usize)> {
    ensure!(
        DEFAULT_LOWER <= lower && lower < upper && upper <= DEFAULT_UPPER,
        "require integer 163 <= lower < upper <= 32768"
    );
    // Validation above bounds all subsequent arithmetic well below u32::MAX.
    let next = lower + 1;
    let first = next + (11 - next % 8) % 8;
    ensure!(first < upper, "the expected candidate interval is empty");
    Ok((first, ((upper - 1 - first) / 8 + 1) as usize))
}

fn allowed_prime(p: u32) -> bool {
    if !(3..=97).contains(&p) || p.is_multiple_of(2) {
        return false;
    }
    // Trial division is independent of the producer's prime pool and Euler
    // criterion. The upper bound makes d*d and every later p*p safe.
    let mut d = 3;
    while d * d <= p {
        if p.is_multiple_of(d) {
            return false;
        }
        d += 2;
    }
    true
}

fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a
}

fn bits(value: u32) -> usize {
    (u32::BITS - value.leading_zeros()) as usize
}

/// Verify a complete finite certificate against the caller's expected task.
///
/// Supported bounds satisfy `163 <= expected_lower < expected_upper <= 32768`
/// and must contain at least one candidate `q == 3 (mod 8)`. Bounds, schema,
/// assumptions, types, canonical bitsets and roots, exhaustive disjoint
/// coverage, and all algebraic witnesses are checked. Duplicate and unknown
/// JSON fields are rejected by the typed serde structures.
///
/// Each assigned candidate has either a square divisor `p*p` (and is therefore
/// not a fundamental odd discriminant), or an integral primitive positive
/// quadratic form `(p,b,c)` of discriminant `-q` with `4*p < q`. The latter is
/// conditional obstruction evidence under the explicitly retained assumptions.
///
/// Invalid input returns `Err`; an `Ok` report always has `valid == true` and
/// `global_proof_verified == false`. No producer, optimizer, floating point
/// arithmetic, or external service is used.
pub fn verify(
    bytes: &[u8],
    expected_lower: u32,
    expected_upper: u32,
) -> Result<VerificationReport> {
    ensure!(
        bytes.len() <= MAX_CERTIFICATE_BYTES,
        "certificate input exceeds the 2 MiB limit"
    );
    let (first, count) = bounds(expected_lower, expected_upper)?;
    let certificate: Certificate =
        serde_json::from_slice(bytes).context("invalid certificate JSON or structure")?;
    ensure!(
        certificate.schema == SCHEMA,
        "unsupported certificate schema"
    );
    let expected_domain = Domain {
        lower_exclusive: expected_lower,
        upper_exclusive: expected_upper,
        modulus: 8,
        residue: 3,
        candidate_count: count,
    };
    ensure!(
        certificate.domain == expected_domain,
        "certificate domain does not match the expected task"
    );
    ensure!(
        certificate.external_dependencies.len() == DEPENDENCIES.len()
            && certificate
                .external_dependencies
                .iter()
                .zip(DEPENDENCIES)
                .all(|(actual, expected)| actual == expected),
        "external assumptions must be stated without alteration"
    );
    ensure!(
        !certificate.global_proof_verified,
        "the finite certificate cannot claim a global proof"
    );
    ensure!(
        certificate.complete && certificate.uncovered.is_empty(),
        "incomplete cover"
    );
    ensure!(
        (1..=24).contains(&certificate.groups.len()),
        "require between one and 24 prime groups"
    );

    let byte_count = count.div_ceil(8);
    let encoded_length = 4 * byte_count.div_ceil(3);
    let mut seen = vec![0_u8; byte_count];
    let mut used_primes = BTreeSet::new();
    let mut root_checks = 0;
    let mut candidate_checks = 0;
    let mut witness_bits = 0;
    let mut kinds = WitnessKinds {
        splitting: 0,
        ramified: 0,
        square_divisor: 0,
    };

    for group in &certificate.groups {
        let p = group.prime;
        ensure!(
            allowed_prime(p) && used_primes.insert(p),
            "illegal or repeated prime"
        );
        ensure!(group.mask.len() == encoded_length, "wrong bitset length");
        let raw = STANDARD
            .decode(group.mask.as_bytes())
            .context("malformed base64 bitset")?;
        ensure!(raw.len() == byte_count, "wrong decoded bitset length");
        ensure!(STANDARD.encode(&raw) == group.mask, "noncanonical bitset");
        ensure!(
            raw.iter().any(|&byte| byte != 0),
            "empty candidate assignment"
        );
        let remainder = count % 8;
        if remainder != 0 {
            let allowed = (1_u8 << remainder) - 1;
            ensure!(
                raw[byte_count - 1] & !allowed == 0,
                "candidate assignment has out of domain bits"
            );
        }
        ensure!(
            raw.iter().zip(&seen).all(|(&new, &old)| new & old == 0),
            "overlapping candidate assignment"
        );
        ensure!(
            (1..=p.div_ceil(2) as usize).contains(&group.roots.len()),
            "invalid number of root witnesses"
        );
        let mut roots = [None; 97];
        let mut previous = None;
        for &[residue, root] in &group.roots {
            ensure!(
                residue < p
                    && previous.is_none_or(|old| old < residue)
                    && root <= (p - 1) / 2
                    && root * root % p == residue,
                "wrong or noncanonical modular square root"
            );
            roots[residue as usize] = Some(root);
            previous = Some(residue);
            root_checks += 1;
        }
        let mut used_residues = [false; 97];

        // Scan the full authoritative domain, independently of any producer's
        // selected-bit extraction or primality/squarefree filtering.
        for index in 0..count {
            if raw[index / 8] & (1_u8 << (index % 8)) == 0 {
                continue;
            }
            let q = first + 8 * index as u32;
            ensure!(4 * p < q, "prime fails the strict norm threshold");
            let residue = (p - q % p) % p;
            let root = roots[residue as usize].context("missing modular square root witness")?;
            used_residues[residue as usize] = true;
            candidate_checks += 1;
            witness_bits += bits(p) + bits(root);

            if q.is_multiple_of(p * p) {
                ensure!(root == 0, "wrong square divisor witness");
                kinds.square_divisor += 1;
                continue;
            }
            // Choose an odd representative of a root modulo 2p. In conjunction
            // with q == 3 mod 8, this must give an integral primitive form.
            let b = if root % 2 == 1 { root } else { p - root };
            let numerator = b * b + q;
            ensure!(
                numerator.is_multiple_of(4 * p),
                "root does not yield an integral quadratic form"
            );
            let c = numerator / (4 * p);
            let discriminant = i64::from(b) * i64::from(b) - 4 * i64::from(p) * i64::from(c);
            ensure!(
                c > 0 && discriminant == -i64::from(q) && gcd(gcd(p, b), c) == 1,
                "invalid or imprimitive quadratic form witness"
            );
            if root == 0 {
                kinds.ramified += 1;
            } else {
                kinds.splitting += 1;
            }
        }
        ensure!(
            (0..p as usize).all(|residue| used_residues[residue] == roots[residue].is_some()),
            "unused root records are not canonical"
        );
        for (old, new) in seen.iter_mut().zip(raw) {
            *old |= new;
        }
    }
    ensure!(
        (0..count).all(|index| seen[index / 8] & (1_u8 << (index % 8)) != 0)
            && candidate_checks == count,
        "the exhaustive candidate universe is not covered"
    );

    Ok(VerificationReport {
        valid: true,
        lower_exclusive: expected_lower,
        upper_exclusive: expected_upper,
        candidates: count,
        covered: count,
        uncovered: 0,
        certificate_sha256: format!("{:x}", Sha256::digest(bytes)),
        certificate_bytes: bytes.len(),
        used_primes: certificate.groups.iter().map(|group| group.prime).collect(),
        candidate_witness_checks: candidate_checks,
        root_witness_checks: root_checks,
        verifier_bit_tests: count * certificate.groups.len(),
        verifier_checks: candidate_checks + root_checks,
        witness_bits,
        witness_kinds: kinds,
        global_proof_verified: false,
    })
}

//! Pinned upstream tools with bounded local authority.
//!
//! Recall uses lexical features, not a semantic embedding model. Admission is
//! structural and does not replace the independent certificate checker.

use agl_types::{
    Applicability, Authority, Genome, HardGates, HardInvariant, Mutation, MutationScope,
};
use anyhow::{ensure, Context, Result};
use constitution::{Constitution, RoleKeys};
use ruvector_core::index::{hnsw::HnswIndex, VectorIndex};
use ruvector_core::types::{DistanceMetric, HnswConfig};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

pub const RGI_COMMIT: &str = "fe5456234bcae654c513d1360f6f2d67d5933fb3";
pub const AUTOGENOUS_COMMIT: &str = "905aa6cbe213392f8b3cab5d4f17bc3a48e0a509";
pub const RUVECTOR_VERSION: &str = "2.4.0";
pub const RECALL_FEATURES: &str = "sha256_token_counts_l2_v1";
const DIMENSIONS: usize = 512;
const MAX_NOTES: usize = 4096;
const MAX_NOTE_BYTES: usize = 16_384;
const MAX_TOTAL_NOTE_BYTES: usize = 4 * 1024 * 1024;
const MAX_QUERY_BYTES: usize = 8192;
const MAX_RECALL_LIMIT: usize = 100;

/// Evaluate only the local certificate verifier with an external spend budget
/// of zero. This pure kernel does not execute work or reserve funds.
pub fn policy(stopped: bool, requested_micros: u64) -> Result<Value> {
    let decision = rgi_core::evaluate(&rgi_core::PolicyInput {
        capability: "certificate.verify".into(),
        allowed_capabilities: vec!["certificate.verify".into()],
        spent_micros: 0,
        reserved_micros: 0,
        requested_micros,
        budget_micros: 0,
        // A fixed policy parameter, not an estimate of mathematical correctness.
        confidence: 1.0,
        min_confidence: 1.0,
        stopped,
    });
    Ok(json!({
        "schema": 1,
        "engine": "rgi-core",
        "upstream_api": "rgi_core::evaluate",
        "upstream_commit": RGI_COMMIT,
        "allowed": decision.allowed,
        "reason": decision.reason,
        "capability": "certificate.verify",
        "budget_micros": 0,
        "requested_micros": requested_micros,
        "external_api_calls": 0
    }))
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct ResearchNote {
    pub id: String,
    pub text: String,
}

/// A lexical cosine similarity score in [0, 1]; larger is closer. Hash
/// collisions can produce false matches. This is not confidence or proof.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct RecallHit {
    pub id: String,
    pub text: String,
    pub score: f32,
}

fn token_features(text: &str) -> Option<Vec<f32>> {
    let mut vector = vec![0.0_f32; DIMENSIONS];
    let mut count = 0;
    for token in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|s| !s.is_empty())
    {
        let hash = Sha256::digest(token.to_lowercase().as_bytes());
        let bucket = usize::from(u16::from_le_bytes([hash[0], hash[1]])) % DIMENSIONS;
        vector[bucket] += 1.0;
        count += 1;
    }
    if count == 0 {
        return None;
    }
    let norm = vector.iter().map(|x| x * x).sum::<f32>().sqrt();
    for value in &mut vector {
        *value /= norm;
    }
    Some(vector)
}

/// Search a transient, actual RuVector HNSW index. The index is rebuilt for
/// each call; nothing is persisted and no network or embedding API is used.
/// Features are deterministic, case folded, hashed token counts. They do not
/// recognize synonyms. HNSW is approximate and hash collisions remain possible.
///
/// Bounds: 4096 notes, 16 KiB per note, 4 MiB combined text, 8 KiB query,
/// 128 byte unique note identifiers, and at most 100 requested hits.
pub fn recall(notes: &[ResearchNote], query: &str, limit: usize) -> Result<Vec<RecallHit>> {
    ensure!(notes.len() <= MAX_NOTES, "recall exceeds 4096 notes");
    ensure!(
        query.len() <= MAX_QUERY_BYTES,
        "recall query exceeds 8192 bytes"
    );
    ensure!(limit <= MAX_RECALL_LIMIT, "recall limit exceeds 100");
    if limit == 0 || notes.is_empty() {
        return Ok(Vec::new());
    }
    let query_vector = token_features(query).context("recall query has no alphanumeric tokens")?;
    let mut by_id = BTreeMap::new();
    let mut total_bytes = 0_usize;
    for note in notes {
        ensure!(
            !note.id.trim().is_empty()
                && note.id.len() <= 128
                && !note.id.chars().any(char::is_control),
            "note identifiers must contain 1 to 128 bytes without control characters"
        );
        ensure!(
            note.text.len() <= MAX_NOTE_BYTES,
            "note text exceeds 16384 bytes"
        );
        total_bytes = total_bytes
            .checked_add(note.text.len())
            .context("note byte count overflow")?;
        ensure!(
            total_bytes <= MAX_TOTAL_NOTE_BYTES,
            "combined note text exceeds 4 MiB"
        );
        ensure!(
            by_id.insert(note.id.as_str(), note).is_none(),
            "duplicate note identifier"
        );
    }
    let mut index = HnswIndex::new(
        DIMENSIONS,
        DistanceMetric::Cosine,
        HnswConfig {
            m: 16,
            ef_construction: 100,
            ef_search: 128,
            max_elements: notes.len(),
        },
    )
    .context("create RuVector HNSW index")?;
    // Stable ID order makes construction independent of caller array ordering.
    for (id, note) in &by_id {
        let vector = token_features(&note.text).context("note text has no alphanumeric tokens")?;
        index
            .add((*id).to_owned(), vector)
            .context("insert note into RuVector HNSW index")?;
    }
    let results = index
        .search(&query_vector, limit.min(notes.len()))
        .context("search RuVector HNSW index")?;
    let mut hits = Vec::with_capacity(results.len());
    for result in results {
        ensure!(
            result.score.is_finite(),
            "RuVector returned a nonfinite distance"
        );
        let note = by_id
            .get(result.id.as_str())
            .context("RuVector returned an unknown note identifier")?;
        let similarity = (1.0 - result.score).clamp(0.0, 1.0);
        if similarity > 0.0 {
            hits.push(RecallHit {
                id: note.id.clone(),
                text: note.text.clone(),
                score: similarity,
            });
        }
    }
    hits.sort_by(|a, b| b.score.total_cmp(&a.score).then_with(|| a.id.cmp(&b.id)));
    Ok(hits)
}

fn admission_inputs(
    certificate_hash: &str,
    candidates: usize,
) -> Result<(Constitution, Genome, Mutation)> {
    ensure!(
        certificate_hash.len() == 64
            && certificate_hash
                .bytes()
                .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c)),
        "certificate hash must be a lowercase SHA256 digest"
    );
    ensure!(candidates > 0, "candidate count must be positive");
    let constitution = Constitution {
        identity: "polymath-local-evidence-v1".into(),
        version: 1,
        authority_ceiling: Authority::AutoReversible,
        prohibited_effects: [
            "capability_expansion",
            "budget_expansion",
            "network_access",
            "secret_access",
            "checker_change",
            "domain_change",
            "code_change",
            "policy_change",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect(),
        hard_gates: HardGates::default(),
        signers: Vec::new(),
        pinned_keys: RoleKeys::default(),
        effective_at: 0,
    };
    let invariants: Vec<HardInvariant> = [
        "digest_well_formed",
        "positive_declared_candidate_count",
        "zero_external_spend",
        "no_capability_expansion",
    ]
    .into_iter()
    .map(|name| HardInvariant {
        name: name.into(),
        holds: true,
    })
    .collect();
    // A fixed structural baseline, not a claim about a deployed artifact pointer.
    let parent_hash = format!(
        "{:x}",
        Sha256::digest(b"polymath-local-evidence-baseline-v1")
    );
    let parent = Genome {
        hash: parent_hash.clone(),
        identity: "polymath-certificate-evidence".into(),
        constitution: constitution.hash(),
        capability_ceiling: Authority::AutoReversible,
        hard_invariants: invariants.clone(),
        lineage: Vec::new(),
    };
    let mutation = Mutation {
        id: certificate_hash.into(),
        parent_genome_hash: parent_hash.clone(),
        scope: MutationScope::CacheMemory,
        requested_authority: Authority::AutoReversible,
        applicability: Applicability {
            workloads: vec!["certificate_evidence_registration".into()],
            environments: vec!["local_cpu".into()],
            jurisdictions: Vec::new(),
        },
        preserved_invariants: invariants,
        rollback_target: Some(parent_hash),
        expires_at: None,
        signature: None,
    };
    Ok((constitution, parent, mutation))
}

/// Structural admission for metadata supplied after certificate replay by the
/// caller. This function has no certificate bytes, so it cannot verify the hash
/// binding, candidate count, coverage, or mathematical truth. No pointer moves.
pub fn admit_verified(certificate_hash: &str, candidates: usize) -> Result<Value> {
    let (constitution, parent, mutation) = admission_inputs(certificate_hash, candidates)?;
    // Never fabricate upstream fitness or signed judge receipts.
    let verdict = verifier::verify(&constitution, &parent, &mutation, &[], None, 0);
    Ok(json!({
        "schema": 1,
        "engine": "autogenous",
        "upstream_api": "verifier::verify",
        "upstream_commit": AUTOGENOUS_COMMIT,
        "structural_admission_allowed": verdict.admissible,
        "upstream_admission_allowed": verdict.admissible,
        "upstream_promotable": verdict.promotable,
        "upstream_violations": verdict.violations,
        "constitution_sha256": constitution.hash(),
        "certificate_sha256": certificate_hash,
        "declared_candidates": candidates,
        "input_evidence": "caller_supplied_metadata",
        "mathematical_truth_verified": false,
        "certificate_verified_by_this_function": false,
        "signed_two_judge_promotion": false,
        "deployment_rollback_executed": false,
        "external_api_calls": 0
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn note(id: &str, text: &str) -> ResearchNote {
        ResearchNote {
            id: id.into(),
            text: text.into(),
        }
    }

    #[test]
    fn upstream_policy_allows_only_zero_spend_and_respects_stop() {
        assert_eq!(policy(false, 0).unwrap()["allowed"], true);
        for amount in [1, 100, u64::MAX] {
            let verdict = policy(false, amount).unwrap();
            assert_eq!(verdict["allowed"], false);
            assert_eq!(verdict["reason"], "budget_exhausted");
        }
        assert_eq!(policy(true, u64::MAX).unwrap()["reason"], "stopped");
    }

    #[test]
    fn lexical_features_are_normalized_and_case_folded() {
        assert_eq!(
            token_features("Prime, certificate!"),
            token_features("CERTIFICATE prime")
        );
        let vector = token_features("prime prime certificate").unwrap();
        assert!((vector.iter().map(|x| x * x).sum::<f32>() - 1.0).abs() < 1e-6);
        assert_ne!(token_features("cat"), token_features("dog"));
        assert_ne!(token_features("dog"), token_features("god"));
        assert!(token_features("!? ").is_none());
    }

    #[test]
    fn actual_hnsw_returns_lexically_closest_note() {
        let notes = vec![
            note("proof", "prime certificate residue"),
            note("unrelated", "garden orange cloud"),
            note("partial", "prime residue divisor field"),
        ];
        let hits = recall(&notes, "prime certificate residue", 3).unwrap();
        assert_eq!(hits[0].id, "proof");
        assert!((hits[0].score - 1.0).abs() < 1e-6);
        assert!(hits.iter().all(|hit| (0.0..=1.0).contains(&hit.score)));
        assert!(hits.windows(2).all(|w| w[0].score >= w[1].score));
        let mut reversed = notes.clone();
        reversed.reverse();
        assert_eq!(
            hits,
            recall(&reversed, "prime certificate residue", 3).unwrap()
        );
    }

    #[test]
    fn hnsw_handles_empty_singleton_and_limits() {
        assert!(recall(&[], "prime", 1).unwrap().is_empty());
        let notes = [note("a", "prime")];
        assert_eq!(recall(&notes, "prime", 10).unwrap().len(), 1);
        assert!(recall(&notes, "prime", 0).unwrap().is_empty());
        assert!(recall(&notes, "prime", 101).is_err());
        assert!(recall(&notes, "?!", 1).is_err());
        assert!(recall(&notes, &"x".repeat(MAX_QUERY_BYTES + 1), 1).is_err());
    }

    #[test]
    fn recall_rejects_ambiguous_or_oversized_notes() {
        assert!(recall(&[note("a", "prime"), note("a", "residue")], "prime", 1).is_err());
        assert!(recall(&[note("a\n", "prime")], "prime", 1).is_err());
        assert!(recall(&[note("a", "!!!")], "prime", 1).is_err());
        assert!(recall(&[note("a", &"p".repeat(MAX_NOTE_BYTES + 1))], "prime", 1).is_err());
        assert!(recall(&vec![note("a", "prime"); MAX_NOTES + 1], "prime", 1).is_err());
    }

    #[test]
    fn autogenous_admits_structure_without_mathematical_or_promotion_claims() {
        let out = admit_verified(&"0".repeat(64), 4075).unwrap();
        assert_eq!(out["upstream_admission_allowed"], true);
        for field in [
            "upstream_promotable",
            "mathematical_truth_verified",
            "certificate_verified_by_this_function",
            "signed_two_judge_promotion",
            "deployment_rollback_executed",
        ] {
            assert_eq!(out[field], false, "{field}");
        }
        assert!(admit_verified(&"0".repeat(64), 0).is_err());
        for hash in [
            "abc".to_owned(),
            "g".repeat(64),
            "A".repeat(64),
            "0".repeat(65),
        ] {
            assert!(admit_verified(&hash, 1).is_err());
        }
    }

    #[test]
    fn actual_autogenous_rejects_authority_invariant_and_effect_expansion() {
        let (constitution, parent, mutation) = admission_inputs(&"1".repeat(64), 4075).unwrap();
        let mut expanded = mutation.clone();
        expanded.requested_authority = Authority::Governed;
        assert!(!verifier::verify(&constitution, &parent, &expanded, &[], None, 0).admissible);
        let mut lost = mutation.clone();
        lost.preserved_invariants.clear();
        assert!(!verifier::verify(&constitution, &parent, &lost, &[], None, 0).admissible);
        let mut irreversible = mutation.clone();
        irreversible.rollback_target = None;
        assert!(!verifier::verify(&constitution, &parent, &irreversible, &[], None, 0).admissible);
        for effect in [
            "budget_expansion",
            "network_access",
            "checker_change",
            "capability_expansion",
        ] {
            assert!(
                !verifier::verify(&constitution, &parent, &mutation, &[effect.into()], None, 0)
                    .admissible
            );
        }
    }
}
